<template><div class="p-6 md:p-8"><div class="mb-6"><h1 class="text-2xl font-semibold text-gray-900">{{ title }}</h1><p class="mt-1 text-sm text-gray-500">Review intake details and record follow-up. Status changes do not send email.</p></div><div class="mb-4 flex flex-wrap gap-3"><input v-model="search" class="rounded-lg border-gray-300 text-sm" placeholder="Search name, company or email" @keyup.enter="load"><select v-model="status" class="rounded-lg border-gray-300 text-sm"><option value="">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{ s.replaceAll('_',' ') }}</option></select><button class="rounded-lg bg-brand-600 px-4 py-2 text-sm font-semibold text-white" @click="load">Search</button></div><div v-if="error" role="alert" class="mb-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{ error }}</div><div class="overflow-x-auto rounded-xl border border-gray-200 bg-white"><table class="min-w-full text-left text-sm"><thead class="bg-gray-50 text-xs text-gray-500"><tr><th class="p-4">Contact</th><th class="p-4">Organization</th><th class="p-4">Submitted</th><th class="p-4">Source</th><th class="p-4">Consent</th><th class="p-4">Status</th><th class="p-4">Email</th><th class="p-4">Follow-up</th><th v-if="kind==='agency'" class="p-4">Access</th></tr></thead><tbody><tr v-for="item in result?.items||[]" :key="item.id" class="border-t border-gray-100"><td class="p-4"><strong class="block text-gray-900">{{item.contact_name}}</strong><a class="text-indigo-700" :href="`mailto:${item.email}`">{{item.email}}</a></td><td class="p-4">{{item.company_name||item.brand_name}}</td><td class="p-4 whitespace-nowrap">{{new Date(item.created_at).toLocaleString()}}</td><td class="p-4">{{item.source||'Direct'}}</td><td class="p-4">{{item.consent_version}}<small class="block text-gray-500">{{new Date(item.consent_at).toLocaleString()}}</small><small>Marketing: {{item.marketing_consent?'yes':'no'}}</small></td><td class="p-4">{{item.status.replaceAll('_',' ')}}</td><td class="p-4">{{item.delivery_status.replaceAll('_',' ')}}</td><td class="p-4"><select :value="item.status" class="rounded border-gray-300 text-xs" @change="update(item,$event)"><option v-for="s in statuses" :key="s" :value="s">{{s.replaceAll('_',' ')}}</option></select></td><td v-if="kind==='agency'" class="p-4"><button class="text-indigo-700 underline" @click="showHistory(item)">Invitation history</button><button v-if="['in_review','invited'].includes(item.status)" class="ml-3 text-indigo-700 underline" @click="createInvite(item)">Invite or reissue</button><button v-if="item.status==='invited'" class="ml-3 text-red-700 underline" @click="cancelInvite(item)">Cancel</button></td></tr><tr v-if="!loading && !result?.items.length"><td colspan="9" class="p-12 text-center text-gray-500">No requests match these filters.</td></tr></tbody></table></div><div class="mt-4 flex items-center justify-between text-sm"><span>{{result?.total||0}} requests</span><div class="flex gap-2"><button class="rounded border px-3 py-1 disabled:opacity-40" :disabled="page<=1" @click="page--;load()">Previous</button><span class="px-2 py-1">{{page}} / {{result?.total_pages||1}}</span><button class="rounded border px-3 py-1 disabled:opacity-40" :disabled="page >= (result?.total_pages||1)" @click="page++;load()">Next</button></div></div></div></template>
<script setup lang="ts">import type { OnboardingIntake,PaginatedOnboardingIntake } from '~/types/onboarding';definePageMeta({middleware:'auth'});const props=defineProps<{kind:'agency'|'brand';title:string;statuses:string[]}>();const {get,post}=useApi();const result=ref<PaginatedOnboardingIntake>();const page=ref(1);const pageSize=25;const search=ref('');const status=ref('');const loading=ref(false);const error=ref('');const endpoint=computed(()=>props.kind==='agency'?'/api/v1/admin/agency-access-requests':'/api/v1/admin/brand-waitlist');async function load(){loading.value=true;error.value='';try{result.value=(await get<PaginatedOnboardingIntake>(endpoint.value,{params:{page:page.value,page_size:pageSize,search:search.value||undefined,status:status.value||undefined}})).data}catch(e:any){error.value=e.response?.status===403?'Only Atlas administrators can view this queue.':e.response?.data?.detail||'Queue could not be loaded.'}finally{loading.value=false}}async function update(item:OnboardingIntake,event:Event){const next=(event.target as HTMLSelectElement).value;if(next===item.status)return;const verification_reference=window.prompt('Enter the verified owner follow-up reference:')||'';try{await post(`${endpoint.value}/${item.id}/review`,{status:next,verification_reference});await load()}catch(e:any){error.value=e.response?.data?.detail||'Status could not be updated.';await load()}}async function showHistory(item:OnboardingIntake){try{const data=(await get(`/api/v1/admin/agency-access-requests/${item.id}/status`)).data;const lines=(data.attempts||[]).map((a:any)=>`Generation ${a.generation}: ${a.action}, ${a.delivery_status}`).join('\n')||'No invitations sent';window.alert(`Request: ${data.status}\nAccount: ${data.account_status||'not accepted'}\nUser: ${data.linked_user_id||'not linked'}\n\n${lines}`)}catch(e:any){error.value=e.response?.data?.detail||'Invitation history could not be loaded.'}}async function createInvite(item:OnboardingIntake){const role=window.prompt('Role: org_owner, org_admin, or mcn_operator','org_owner');if(!role)return;const organizationId=window.prompt('Organization ID (required for organization roles)')||'';const mcnId=role==='mcn_operator'?(window.prompt('MCN ID (required for MCN operator)')||''):'';const bundle:any[]=[];if(organizationId)bundle.push({entity_type:'organization',entity_id:organizationId});if(mcnId)bundle.push({entity_type:'mcn_partner',entity_id:mcnId});try{await post(`/api/v1/admin/agency-access-requests/${item.id}/invite`,{role,assignment_bundle:bundle},{headers:{'Idempotency-Key':crypto.randomUUID()}});await load()}catch(e:any){error.value=e.response?.data?.detail||'Invitation could not be created.'}}async function cancelInvite(item:OnboardingIntake){if(!window.confirm('Cancel this invitation and invalidate its link?'))return;try{await post(`/api/v1/admin/agency-access-requests/${item.id}/invitation-action`,{action:'cancel'});await load()}catch(e:any){error.value=e.response?.data?.detail||'Invitation could not be cancelled.'}}onMounted(load)</script>